  var d = Math.round(h / 24); if (d < 30) return '\u0642\u0628\u0644 ' + (d === 1 ? '\u064A\u0648\u0645' : d === 2 ? '\u064A\u0648\u0645\u064A\u0646' : d + ' \u064A\u0648\u0645');
