function renderAuth() {
  var setup = S.boot && S.boot.setup;
  app.innerHTML = '<div class="auth"><div class="auth-card"><div class="logo">IF</div><h1>' + (setup ? '\u062A\u062C\u0647\u064A\u0632 \u0644\u0648\u062D\u0629 \u0627\u0644\u062A\u062D\u0643\u0645' : '\u0644\u0648\u062D\u0629 \u062A\u062D\u0643\u0645 \u0639\u0631\u0627\u0642 \u0641\u064A\u062A') + '</h1><p>' + (setup ? '\u0623\u0648\u0644 \u0645\u0631\u0629 \u062A\u0641\u062A\u062D \u0627\u0644\u0644\u0648\u062D\u0629. \u0633\u0648\u0651\u064A \u062D\u0633\u0627\u0628\u0643 \u0643\u0645\u0633\u0624\u0648\u0644 \u0631\u0626\u064A\u0633\u064A. \u062A\u062D\u062A\u0627\u062C \u0631\u0645\u0632 \u0627\u0644\u062A\u062C\u0647\u064A\u0632 (SETUP_CODE) \u0627\u0644\u0644\u064A \u0628\u0625\u0639\u062F\u0627\u062F\u0627\u062A \u0627\u0644\u0640Worker.' : '\u0633\u062C\u0651\u0644 \u062F\u062E\u0648\u0644 \u0628\u062D\u0633\u0627\u0628\u0643.') + '</p><form id="af" autocomplete="on">' +
    (setup ? '<label>\u0631\u0645\u0632 \u0627\u0644\u062A\u062C\u0647\u064A\u0632<input class="inp" name="code" type="password" autocomplete="off" required dir="ltr"></label><label>\u0627\u0633\u0645\u0643<input class="inp" name="name" required value="Joe"></label>' : '') +
    '<label>\u0627\u0633\u0645 \u0627\u0644\u0645\u0633\u062A\u062E\u062F\u0645<input class="inp" name="username" autocomplete="username" required dir="ltr" autocapitalize="none" spellcheck="false" placeholder="joe"></label><label>\u0643\u0644\u0645\u0629 \u0627\u0644\u0633\u0631<div class="pw"><input class="inp" name="password" type="password" autocomplete="' + (setup ? 'new-password' : 'current-password') + '" required minlength="' + (setup ? 8 : 1) + '" dir="ltr"><button type="button" class="btn ghost icon" data-pw aria-label="\u0625\u0638\u0647\u0627\u0631">' + ic('eye') + '</button></div></label>' +
    '<div class="err" id="aerr" role="alert"></div><button class="btn pri" type="submit">' + (setup ? '\u0633\u0648\u0651\u064A \u0627\u0644\u062D\u0633\u0627\u0628 \u0648\u0627\u062F\u062E\u0644' : '\u062F\u062E\u0648\u0644') + '</button></form>' + (setup && S.boot && !S.boot.setupReady ? '<div class="note warn" style="margin-top:14px">' + ic('alert') + '<div>SETUP_CODE \u0645\u0648 \u0645\u0648\u062C\u0648\u062F \u0628\u0625\u0639\u062F\u0627\u062F\u0627\u062A \u0627\u0644\u0640Worker.</div></div>' : '') + '</div></div>';
  var f = $('#af');
  $('[data-pw]').onclick = function () { var i = f.password; i.type = i.type === 'password' ? 'text' : 'password'; };
  f.onsubmit = function (e) {
    e.preventDefault();
    var b = f.querySelector('button[type=submit]'), err = $('#aerr'); err.textContent = ''; b.disabled = true;
    var body = { username: f.username.value, password: f.password.value };
    if (setup) { body.code = f.code.value; body.name = f.name.value; }
    api(setup ? '/setup' : '/login', { body: body }).then(function (r) { S.me = r.me; return start(); }).catch(function (e2) { err.textContent = e2.message; b.disabled = false; });
  };
  setTimeout(function () { var i = f.querySelector('input'); i && i.focus(); }, 50);
}
function loadCfg() { return api('/config').then(function (r) { S.cfg = r.cfg; S.ui = r.ui; S.meta = r.meta; S.rev = r.rev; rebase(); }); }
function start() {
  app.innerHTML = '<div class="auth"><span class="spin"></span></div>';
  return loadCfg().then(function () { renderShell(); var h = parseHash(); S.route = h.r; if (h.s) S.sub[h.r] = h.s; renderPage(); });
}
function boot() {
  api('/boot').then(function (r) { S.boot = r; if (r.me) { S.me = r.me; start().catch(function (e) { errToast(e); renderAuth(); }); } else renderAuth(); })
    .catch(function (e) { app.innerHTML = '<div class="auth"><div class="auth-card"><h1>\u0645\u0627 \u0627\u0634\u062A\u063A\u0644\u062A \u0627\u0644\u0644\u0648\u062D\u0629</h1><p>' + esc(e.message) + '</p><button class="btn pri" onclick="location.reload()">\u062C\u0631\u0651\u0628 \u0645\u0631\u0629 \u062B\u0627\u0646\u064A\u0629</button></div></div>'; });
}

/* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 \u0627\u0644\u0631\u0626\u064A\u0633\u064A\u0629 \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 */
var STATE_TONE = { open: 'ok', closed: '', full: 'warn', soon: 'info', custom: 'ac' };
PAGES.overview = {
  html: function () {
    var c = S.cfg, g = c.gate;
    var states = Object.keys(S.meta.gateStates);
    var gateCard = card('\u062D\u0627\u0644\u0629 \u0627\u0644\u0627\u0634\u062A\u0631\u0627\u0643\u0627\u062A', '<div class="row" style="margin-bottom:12px"><span class="chip ' + (STATE_TONE[g.state] || '') + '"><span class="dot"></span>' + esc(String(S.meta.gateStates[g.state] || g.state).replace(/^[^\u0600-\u06FF]+/, '')) + '</span><span class="muted small">' + esc(cut(T(g.text), 120)) + '</span></div>' +
      (can('gate') ? '<div class="row">' + states.filter(function (s) { return s !== 'custom'; }).map(function (s) { return '<button class="btn sm' + (g.state === s ? ' pri' : '') + '" data-act="ovState" data-v="' + s + '">' + esc(String(S.meta.gateStates[s]).replace(/^[^\u0600-\u06FF]+/, '')) + '</button>'; }).join('') + '<button class="btn sm ghost" data-go="gate">' + ic('door') + '\u0643\u0644 \u0627\u0644\u0625\u0639\u062F\u0627\u062F\u0627\u062A</button></div>' : ''), { icon: 'door' });
    var modeCard = card('\u0648\u0636\u0639 \u0627\u0644\u0645\u0648\u0642\u0639', '<div class="row"><span class="chip ' + (c.mode === 'live' ? 'ok' : c.mode === 'maintenance' ? 'warn' : 'bad') + '"><span class="dot ' + (c.mode === 'live' ? 'pulse' : '') + '"></span>' + esc(String(S.meta.modes[c.mode] || c.mode).replace(/^[^\u0600-\u06FF]+/, '')) + '</span>' + (can('mode') ? '<button class="btn sm ghost" data-go="mode">\u063A\u064A\u0651\u0631</button>' : '') + '</div><hr class="s"><div class="small muted">\u0622\u062E\u0631 \u062A\u0639\u062F\u064A\u0644: ' + ago(c.updatedAt) + (c.updatedBy && c.updatedBy.name ? ' \xB7 ' + esc(c.updatedBy.name) : '') + '<br>\u0627\u0644\u0625\u0635\u062F\u0627\u0631: <b class="num">' + esc((c.changelog && c.changelog.version) || '\u2014') + '</b> \xB7 \u0646\u0633\u062E\u0629 \u0627\u0644\u0625\u0639\u062F\u0627\u062F\u0627\u062A <b class="num">r' + S.rev + '</b></div>', { icon: 'power' });
    return pageHead('\u0623\u0647\u0644\u064B\u0627 ' + esc((S.me.name || '').split(' ')[0]) + ' \u{1F44B}', '\u0646\u0638\u0631\u0629 \u0633\u0631\u064A\u0639\u0629 \u0639\u0644\u0649 \u0627\u0644\u0645\u0648\u0642\u0639 \u0647\u0633\u0647.', '<a class="btn" href="/" target="_blank" rel="noopener">' + ic('ext') + '\u0627\u0641\u062A\u062D \u0627\u0644\u0645\u0648\u0642\u0639</a>') +
      '<div id="ovK" class="grid g4">' + [1, 2, 3, 4].map(function () { return '<div class="skel" style="height:104px"></div>'; }).join('') + '</div>' +
      '<div class="grid g2" style="margin-top:14px"><div>' + gateCard + modeCard + '</div><div id="ovR">' + (can('stats') ? card('\u0627\u0644\u0645\u062A\u0635\u0641\u062D\u064A\u0646 \u0647\u0633\u0647', '<div id="ovLive"><div class="skel" style="height:140px"></div></div>', { icon: 'pulse', right: '<button class="btn sm ghost" data-go="live">\u0627\u0644\u0643\u0644</button>' }) : '') + (can('history.view') ? card('\u0622\u062E\u0631 \u0627\u0644\u062A\u0639\u062F\u064A\u0644\u0627\u062A', '<div id="ovH"><div class="skel" style="height:120px"></div></div>', { icon: 'history', right: '<button class="btn sm ghost" data-go="history">\u0627\u0644\u0633\u062C\u0644</button>' }) : '') + '</div></div>';
  },
  mount: function (el) {
    var load = function () {
      api('/overview').then(function (r) {
        var k = $('#ovK', el); if (!k) return;
        var st = r.stats, t = st ? st.today : {}, y = st ? st.yesterday : {};
        var dl = function (a, b) { if (!b) return '<span class="muted">\u0623\u0645\u0633 ' + n(b) + '</span>'; var d = pct(a, b); return '<span class="' + (d >= 0 ? 'up' : 'down') + '">' + (d >= 0 ? '\u25B2' : '\u25BC') + ' ' + Math.abs(d) + '%</span> <span class="muted">\u0639\u0646 \u0623\u0645\u0633 (' + n(b) + ')</span>'; };
        var tiles = [];
        if (st) {
          tiles.push('<div class="kpi"><span class="l"><span class="dot pulse" style="color:var(--ok)"></span>\u064A\u062A\u0635\u0641\u062D\u0648\u0646 \u0647\u0633\u0647</span><span class="v num">' + n(st.live) + '</span><span class="d muted">' + n(st.hour) + ' \u062E\u0644\u0627\u0644 \u0622\u062E\u0631 \u0633\u0627\u0639\u0629</span></div>');
          tiles.push('<div class="kpi"><span class="l">' + ic('chart') + '\u0632\u064A\u0627\u0631\u0627\u062A \u0627\u0644\u064A\u0648\u0645</span><span class="v num">' + n(t.views) + '</span><span class="d">' + dl(t.views || 0, y.views || 0) + '</span></div>');
          tiles.push('<div class="kpi"><span class="l">' + ic('users') + '\u0632\u0648\u0627\u0631 \u0627\u0644\u064A\u0648\u0645</span><span class="v num">' + n(t.uniq) + '</span><span class="d">' + dl(t.uniq || 0, y.uniq || 0) + '</span></div>');
          $('#navLive') && ($('#navLive').hidden = !st.live, $('#navLive').textContent = st.live);
        }
        if (r.wait != null) { tiles.push('<div class="kpi"><span class="l">' + ic('bell') + '\u0627\u0644\u0645\u0646\u062A\u0638\u0631\u0648\u0646</span><span class="v num">' + n(r.wait) + '</span><span class="d muted">\u064A\u0646\u062A\u0638\u0631\u0648\u0646 \u0641\u062A\u062D \u0627\u0644\u0627\u0634\u062A\u0631\u0627\u0643\u0627\u062A</span></div>'); $('#navWait') && ($('#navWait').hidden = !r.wait, $('#navWait').textContent = r.wait); }
        if (st) tiles.push('<div class="kpi"><span class="l">' + ic('bolt') + '\u0636\u063A\u0637\u0627\u062A \u0627\u0644\u064A\u0648\u0645</span><span class="v num">' + n((t['e:cta'] || 0) + (t['e:rem'] || 0)) + '</span><span class="d muted">\u0627\u0634\u062A\u0631\u0627\u0643 ' + n(t['e:cta']) + ' \xB7 \u0630\u0643\u0651\u0631\u0646\u064A ' + n(t['e:rem']) + '</span></div>');
        k.innerHTML = tiles.slice(0, 4).join('') || '<div class="kpi"><span class="l">\u0645\u0631\u062D\u0628\u064B\u0627</span><span class="v">\u{1F44B}</span></div>';
        var lv = $('#ovLive', el);
        if (lv && st) lv.innerHTML = st.liveList.length ? '<div class="list">' + st.liveList.slice(0, 5).map(liveRow).join('') + '</div>' : '<div class="empty">' + ic('pulse') + '<div>\u0645\u0627\u0643\u0648 \u0623\u062D\u062F \u064A\u062A\u0635\u0641\u062D \u0647\u0633\u0647</div></div>';
        var hh = $('#ovH', el);
        if (hh && r.recent) hh.innerHTML = r.recent.length ? '<div class="list">' + r.recent.map(function (v) { return '<div class="li"><div class="ic ' + (v.via === 'bot' ? 'info' : v.kind === 'undo' ? 'warn' : 'ac') + '">' + ic(v.via === 'bot' ? 'bot' : v.kind === 'undo' ? 'undo' : v.kind === 'base' ? 'flag' : 'check') + '</div><div class="tx"><b>' + esc(cut(v.what, 90)) + '</b><small>' + esc(v.uname || '') + ' \xB7 ' + ago(v.at) + '</small></div>' + (can('history.undo') && v.kind !== 'base' ? '<button class="btn sm ghost" data-act="ovUndo" data-id="' + v.id + '" title="\u062A\u0631\u0627\u062C\u0639">' + ic('undo') + '</button>' : '') + '</div>'; }).join('') + '</div>' : '<div class="empty">\u0645\u0627\u0643\u0648 \u062A\u0639\u062F\u064A\u0644\u0627\u062A \u0628\u0639\u062F</div>';
      }).catch(errToast);
    };
    load(); every(20000, load);
  }
};
ACT.ovState = function (b) {
  var s = b.dataset.v, pre = S.meta.presets[s];
  quickSave([{ p: ['gate', 'state'], v: s }].concat(pre ? [{ p: ['gate', 'text'], v: clone(pre) }] : []), '\u062D\u0627\u0644\u0629 \u0627\u0644\u0627\u0634\u062A\u0631\u0627\u0643\u0627\u062A \u2190 ' + String(S.meta.gateStates[s]).replace(/^[^\u0600-\u06FF]+/, ''));
};
ACT.ovUndo = function (b) { confirmBox('\u062A\u062A\u0631\u0627\u062C\u0639 \u0639\u0646 \u0647\u0630\u0627 \u0627\u0644\u062A\u0639\u062F\u064A\u0644\u061F', '', '\u062A\u0631\u0627\u062C\u0639').then(function (ok) { ok && undoVersion(Number(b.dataset.id)); }); };
