/* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 \u0623\u062F\u0648\u0627\u062A \u0639\u0627\u0645\u0629 (\u0635\u064A\u0627\u063A\u0629 \u0631\u0633\u0645\u064A\u0629) \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 */
function fAgo(ms) {
  if (!ms) return '\u2014';
  var s = Math.round((Date.now() - ms) / 1000);
  if (s < 45) return '\u0627\u0644\u0622\u0646';
  var m = Math.round(s / 60); if (m < 60) return '\u0645\u0646\u0630 ' + (m === 1 ? '\u062F\u0642\u064A\u0642\u0629' : m === 2 ? '\u062F\u0642\u064A\u0642\u062A\u064A\u0646' : m <= 10 ? m + ' \u062F\u0642\u0627\u0626\u0642' : m + ' \u062F\u0642\u064A\u0642\u0629');
  var h = Math.round(m / 60); if (h < 24) return '\u0645\u0646\u0630 ' + (h === 1 ? '\u0633\u0627\u0639\u0629' : h === 2 ? '\u0633\u0627\u0639\u062A\u064A\u0646' : h <= 10 ? h + ' \u0633\u0627\u0639\u0627\u062A' : h + ' \u0633\u0627\u0639\u0629');
  var d = Math.round(h / 24); if (d < 30) return '\u0645\u0646\u0630 ' + (d === 1 ? '\u064A\u0648\u0645' : d === 2 ? '\u064A\u0648\u0645\u064A\u0646' : d <= 10 ? d + ' \u0623\u064A\u0627\u0645' : d + ' \u064A\u0648\u0645\u064B\u0627');
  return dOnly(ms);
}
function fDur(ms) { var s = Math.max(0, Math.round(ms / 1000)); if (s < 60) return '\u0623\u0642\u0644 \u0645\u0646 \u062F\u0642\u064A\u0642\u0629'; var m = Math.floor(s / 60); if (m < 60) return m + ' \u062F\u0642\u064A\u0642\u0629'; var h = Math.floor(m / 60); return h + ' \u0633\u0627\u0639\u0629' + (m % 60 ? ' \u0648' + (m % 60) + ' \u062F\u0642\u064A\u0642\u0629' : ''); }
function fBytes(b) { b = Number(b) || 0; if (b < 1024) return n(b) + ' \u0628\u0627\u064A\u062A'; if (b < 1048576) return n(Math.round(b / 1024)) + ' \u0643.\u0628'; if (b < 1073741824) return (b / 1048576).toFixed(1) + ' \u0645.\u0628'; return (b / 1073741824).toFixed(2) + ' \u063A.\u0628'; }
